#include "openscale/openscale.hpp"
#include <fstream>
#include <cstring>
#include <sstream>
namespace { struct Header{char magic[8];uint32_t version;uint64_t meta,payload,checksum;}; uint64_t fnv(const std::byte*p,size_t n){uint64_t h=1469598103934665603ull;for(size_t i=0;i<n;i++){h^=uint8_t(p[i]);h*=1099511628211ull;}return h;} }
namespace openscale { Error AvFile::create(const std::filesystem::path&p,const ModelInfo&m,std::span<const std::byte>payload){std::string meta=m.name+"\n"+m.architecture+"\n"+std::to_string(m.parameter_count)+"\n"+std::to_string(m.tensors.size())+"\n";for(auto&t:m.tensors)meta+=t.name+"|"+std::to_string(t.offset)+"|"+std::to_string(t.bytes)+"|"+std::to_string(t.dtype)+"\n";Header h{{'O','P','E','N','S','C','A','L'},1,meta.size(),payload.size(),fnv(payload.data(),payload.size())};std::ofstream f(p,std::ios::binary);if(!f)return{ErrorCode::Io,"create failed"};f.write((char*)&h,sizeof h);f.write(meta.data(),meta.size());f.write((char*)payload.data(),payload.size());return f?Error{}:Error{ErrorCode::Io,"write failed"};}
std::optional<ModelInfo> AvFile::inspect(const std::filesystem::path&p,Error&e){MemoryMap mm;if(e=mm.open(p))return{};if(mm.size()<sizeof(Header)){e={ErrorCode::Format,"truncated"};return{};}Header h{};memcpy(&h,mm.data(),sizeof h);if(memcmp(h.magic,"OPENSCALE",8)!=0||h.version!=1||sizeof(h)+h.meta+h.payload>mm.size()){e={ErrorCode::Format,"invalid AV header"};return{};}std::string s((char*)mm.data()+sizeof(h),h.meta);std::istringstream in(s);ModelInfo m;std::string line;getline(in,m.name);getline(in,m.architecture);getline(in,line);m.parameter_count=std::stoull(line);getline(in,line);size_t n=std::stoull(line);for(size_t i=0;i<n;i++){getline(in,line);auto q=line.find('|');TensorInfo t;t.name=line.substr(0,q);m.tensors.push_back(t);}m.tensor_bytes=h.payload;return m;}
Error AvFile::validate(const std::filesystem::path&p){Error e;auto m=inspect(p,e);if(!m)return e;MemoryMap mm;if(auto x=mm.open(p);x)return x;Header h{};memcpy(&h,mm.data(),sizeof h);auto off=sizeof(h)+h.meta;if(fnv(mm.data()+off,h.payload)!=h.checksum)return{ErrorCode::Corrupt,"payload checksum mismatch"};return{};}}
